# Animation v2 · IF (chương mới) Lặp lại và vô hạn: repeatable, infiniteRepeatable, rememberInfiniteTransition, InfiniteAnimationPolicy
# Nguồn: AnimationSpec.kt @296313a4 (RepeatableSpec, InfiniteRepeatableSpec, RepeatMode, StartOffset); InfiniteTransition.kt @296313a4
# (run(): LaunchedEffect + withInfiniteAnimationFrameNanos, durationScale, animateValue SideEffect/DisposableEffect);
# InfiniteAnimationPolicy.kt @296313a4 (compose/ui); "Customize animations" (an-customize), "Value-based animations" (an-value);
# Essentials 39.5 (repeatable(10, tween(2000), Reverse)); Kunneth Ch.8 (InfiniteRepeatableDemo, keyframes, Reverse).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    m = lambda k, vi, en=None: a('m.repeat.' + k, vi, en)
    m('title', 'Lặp lại: lượt nào đi đâu, và vô hạn dừng khi nào', 'Repeating: where each iteration goes, and when infinite stops')
    m('overview', 'Một giá trị từ 0 tới 1 bằng `tween(300, easing = LinearEasing)`. Bốn cách lặp: `repeatable(3, …, Restart)`, `repeatable(3, …, Reverse)`, `repeatable(2, …, Reverse)` (số lượt chẵn), và `infiniteRepeatable` trong `rememberInfiniteTransition`. Theo dõi mỗi lượt bắt đầu từ đâu, kết thúc ở đâu, và animation vô hạn dừng lúc nào.', 'A value goes from 0 to 1 with `tween(300, easing = LinearEasing)`. Four ways to repeat: `repeatable(3, …, Restart)`, `repeatable(3, …, Reverse)`, `repeatable(2, …, Reverse)` (an even count), and `infiniteRepeatable` inside `rememberInfiniteTransition`. Watch where each iteration starts and ends, and when the infinite animation stops.')
    m('wrapup', '`Restart` mỗi lượt nhảy về đầu rồi đi lại; `Reverse` đi ngược lượt trước nên liền mạch, và KDoc khuyên số lượt LẺ để không bị nhảy tới giá trị cuối khi xong. Animation vô hạn không tự kết thúc: nó chạy trong một `LaunchedEffect` lấy frame qua `withInfiniteAnimationFrameNanos`, nhảy tới đích khi tỉ lệ thời lượng bằng 0, và chỉ dừng khi rời composition.', '`Restart` jumps back to the start for each iteration; `Reverse` plays the previous iteration backwards so it is continuous, and the KDoc recommends an ODD iteration count to avoid jumping to the end value when it finishes. An infinite animation never finishes on its own: it runs in a `LaunchedEffect` taking frames through `withInfiniteAnimationFrameNanos`, snaps to its target when the duration scale is 0, and only stops when it leaves composition.')
    m('simp.1', 'Thời lượng 300 ms và LinearEasing chọn cho số tròn; mỗi bước là một lượt, không phải một frame.', 'The 300 ms duration and LinearEasing are chosen for round numbers; each step is one iteration, not one frame.')
    m('simp.2', 'Bước "nhảy tới giá trị cuối" của lượt chẵn theo câu chữ của KDoc ("có thể"), mô hình không mô phỏng chi tiết bên trong của VectorizedRepeatableSpec.', 'The "jump to the end value" step for an even count follows the KDoc wording ("may"); the model does not simulate VectorizedRepeatableSpec\'s internals.')
    m('ctl.hint', 'So Restart với Reverse, rồi so 3 lượt với 2 lượt.', 'Compare Restart with Reverse, then 3 iterations with 2.')
    m('ctl.which', 'Cách lặp', 'Repetition')
    for k, vi, en in [('restart3', 'repeatable 3 lượt, Restart', 'repeatable, 3 iterations, Restart'), ('reverse3', 'repeatable 3 lượt, Reverse', 'repeatable, 3 iterations, Reverse'), ('reverse2', 'repeatable 2 lượt (chẵn), Reverse', 'repeatable, 2 iterations (even), Reverse'), ('infinite', 'rememberInfiniteTransition', 'rememberInfiniteTransition')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Đồng hồ frame, spec lặp, giá trị, chính sách', 'Frame clock, repeating spec, value, policy')
    m('diagramDesc', 'Đồng hồ frame cấp thời gian cho spec lặp; spec tính giá trị theo lượt; tỉ lệ thời lượng và chính sách can thiệp vào đồng hồ của animation vô hạn', 'The frame clock feeds time to the repeating spec; the spec computes the value per iteration; the duration scale and policy intervene in an infinite animation\'s clock')
    for k, vi, en in [('clock', 'Đồng hồ frame', 'Frame clock'), ('spec', 'Spec lặp', 'Repeating spec'), ('value', 'Giá trị animate', 'Animated value'), ('policy', 'Tỉ lệ thời lượng / chính sách', 'Duration scale / policy')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('ms', 'Thời gian chơi (ms)', 'Play time (ms)'), ('iter', 'Lượt đã xong', 'Iterations done'), ('value', 'Giá trị ×100', 'Value ×100')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('value', 'Giá trị', 'Value'), ('iter', 'Lượt', 'Iteration'), ('mode', 'Chế độ', 'Mode')]:
        m('st.' + k, vi, en)
    S = [
        ('intro', 'Bắt đầu ở 0', 'Starting at 0', 'Spec lặp bọc một spec dựa trên thời lượng (ở đây `tween`). `repeatable` và `infiniteRepeatable` chỉ nhận `DurationBasedAnimationSpec` (tween, keyframes, snap), không nhận spring.', 'The repeating spec wraps a duration-based spec (here `tween`). `repeatable` and `infiniteRepeatable` only accept a `DurationBasedAnimationSpec` (tween, keyframes, snap), not spring.'),
        ('iter.fwd', 'Lượt {i}: {from} → {to}', 'Iteration {i}: {from} → {to}', 'Đi xuôi từ đầu tới cuối trong 300 ms.', 'Forward from start to end in 300 ms.'),
        ('iter.restart', 'Lượt {i}: nhảy về {from}, rồi → {to}', 'Iteration {i}: jump back to {from}, then → {to}', '`RepeatMode.Restart`: mỗi lượt bắt đầu lại từ giá trị đầu, nên có một cú nhảy giữa hai lượt.', '`RepeatMode.Restart`: each iteration starts again from the initial value, so there is a jump between iterations.'),
        ('iter.back', 'Lượt {i}: {from} → {to} (ngược lại)', 'Iteration {i}: {from} → {to} (reversed)', '`RepeatMode.Reverse`: lượt này chơi ngược lượt trước, nên không có cú nhảy.', '`RepeatMode.Reverse`: this iteration plays the previous one backwards, so there is no jump.'),
        ('jumpEnd', 'Hết 2 lượt ở 0, giá trị có thể nhảy tới 1', 'After 2 iterations at 0, the value may jump to 1', 'Số lượt chẵn với Reverse kết thúc ở giá trị đầu, trong khi đích của animation là 1. KDoc cảnh báo animation có thể nhảy tới giá trị cuối khi xong lượt cuối.', 'An even count with Reverse ends at the initial value, while the animation\'s target is 1. The KDoc warns the animation may jump to the end value when it finishes the last iteration.'),
        ('done', 'Xong ở {to}', 'Finished at {to}', '`RepeatableSpec` là `FiniteAnimationSpec`: sau đủ số lượt, animation kết thúc như mọi animation hữu hạn.', '`RepeatableSpec` is a `FiniteAnimationSpec`: after the set number of iterations, the animation finishes like any finite animation.'),
        ('inf.start', 'Vào composition: LaunchedEffect bắt đầu vòng lặp frame', 'Enters composition: a LaunchedEffect starts the frame loop', '`rememberInfiniteTransition` nhớ một `InfiniteTransition` và gọi `run()`: một `LaunchedEffect` lặp `while (true)` lấy frame qua `withInfiniteAnimationFrameNanos`. Con (`animateFloat`) tự đăng ký bằng `DisposableEffect`.', '`rememberInfiniteTransition` remembers an `InfiniteTransition` and calls `run()`: a `LaunchedEffect` loops `while (true)`, taking frames through `withInfiniteAnimationFrameNanos`. The child (`animateFloat`) registers itself with a `DisposableEffect`.'),
        ('inf.iter', 'Lượt {i}: {from} → {to}', 'Iteration {i}: {from} → {to}', 'Mỗi frame, thời gian chơi = (bây giờ − lúc bắt đầu) / durationScale; con tính giá trị từ thời gian đó. Lượt nối lượt, không bao giờ "xong".', 'Each frame, play time = (now − start) / durationScale; the child computes its value from that time. Iteration follows iteration and it never "finishes".'),
        ('inf.scale0', 'Tỉ lệ thời lượng = 0: nhảy tới đích rồi chờ', 'Duration scale = 0: snap to the target and wait', 'Mã ở commit ghim: khi `durationScale` bằng 0, mọi con được `skipToEnd()` (giá trị = đích), rồi vòng lặp treo bằng `snapshotFlow { durationScale }.first { it > 0f }`.', 'Code at the pinned commit: when `durationScale` is 0, every child is `skipToEnd()`ed (value = target), then the loop suspends on `snapshotFlow { durationScale }.first { it > 0f }`.'),
        ('inf.scaleBack', 'Tỉ lệ khác 0 trở lại: chạy lại từ thời gian 0', 'The scale is non-zero again: restart from play time 0', 'Khi tỉ lệ đổi, mốc bắt đầu được đặt lại và mọi con `reset()`, nên animation bắt đầu lại từ đầu chứ không nối tiếp.', 'When the scale changes, the start time is reset and every child is `reset()`, so the animation starts over rather than continuing.'),
        ('inf.leave', 'Rời composition: hủy vòng lặp', 'Leaves composition: the loop is cancelled', 'Coroutine của `LaunchedEffect` bị hủy và `DisposableEffect` gỡ con khỏi transition. Đây là cách duy nhất animation vô hạn dừng "tự nhiên" (KDoc: chỉ dừng khi bị hủy thủ công hoặc composable bị gỡ).', 'The `LaunchedEffect` coroutine is cancelled and the `DisposableEffect` removes the child from the transition. This is the only "natural" way an infinite animation stops (KDoc: only via manual cancellation or when the composable is removed).'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('durationOnly', 'KDoc: RepeatableSpec và InfiniteRepeatableSpec nhận `DurationBasedAnimationSpec`; mã còn ghi TODO "Consider supporting repeating spring specs". [[src:an-spec-src]]', 'The KDoc: RepeatableSpec and InfiniteRepeatableSpec take a `DurationBasedAnimationSpec`; the code even carries the TODO "Consider supporting repeating spring specs". [[src:an-spec-src]]'),
        ('odd', 'KDoc của RepeatableSpec: với Reverse, rất nên dùng số lượt LẺ; nếu không, animation có thể nhảy tới giá trị cuối khi xong lượt cuối. [[src:an-spec-src]]', 'RepeatableSpec\'s KDoc: with Reverse, an ODD number of iterations is highly recommended; otherwise the animation may jump to the end value when it finishes the last iteration. [[src:an-spec-src]]'),
        ('frames', 'Nối với chương EF và B5 của Runtime: LaunchedEffect chạy trên coroutine của composition, frame đến từ MonotonicFrameClock. [[src:an-inftrans-src]]', 'Ties to Runtime chapters EF and B5: the LaunchedEffect runs on the composition\'s coroutine, and frames come from the MonotonicFrameClock. [[src:an-inftrans-src]]'),
        ('scale', 'Tỉ lệ thời lượng là `MotionDurationScale` trong coroutine context; mô hình chỉ theo đúng nhánh `durationScale == 0f` của mã. [[src:an-inftrans-src]]', 'The duration scale is the `MotionDurationScale` in the coroutine context; the model only follows the code\'s `durationScale == 0f` branch. [[src:an-inftrans-src]]'),
        ('leave', 'KDoc của InfiniteRepeatableSpec: không bao giờ tự kết thúc; dùng với transition hay composable animation thì dừng khi composable bị gỡ khỏi cây. [[src:an-spec-src]]', 'InfiniteRepeatableSpec\'s KDoc: it never finishes naturally; used with transitions or animation composables, it stops when the composable is removed from the tree. [[src:an-spec-src]]')]:
        m('co.' + k, vi, en)
    a('cap.repeat', 'Ngoài cùng bên trái là tỉ lệ thời lượng và chính sách, tác động vào đồng hồ frame; đồng hồ cấp thời gian cho spec lặp; spec tính giá trị ở bên phải.', 'Far left is the duration scale and policy, acting on the frame clock; the clock feeds time to the repeating spec; the spec computes the value on the right.')

    C = 'if'
    a(C + '.title', 'Lặp lại và vô hạn: repeatable, infiniteRepeatable, InfiniteTransition', 'Repeating and infinite: repeatable, infiniteRepeatable, InfiniteTransition')
    a(C + '.essence',
      '`repeatable(n, spec, mode)` lặp một spec dựa trên thời lượng n lần; `Restart` nhảy về đầu mỗi lượt, `Reverse` đi ngược và nên dùng số lượt lẻ.\n`infiniteRepeatable` không bao giờ tự xong; `rememberInfiniteTransition` chạy nó trong một LaunchedEffect và chỉ dừng khi rời composition.\nKhi tỉ lệ thời lượng bằng 0, animation vô hạn nhảy tới đích và chờ; trong ComposeTestRule nó không chạy (chương C8).',
      '`repeatable(n, spec, mode)` repeats a duration-based spec n times; `Restart` jumps back each iteration, `Reverse` plays backwards and should use an odd count.\n`infiniteRepeatable` never finishes on its own; `rememberInfiniteTransition` runs it in a LaunchedEffect, and it only stops when it leaves composition.\nWhen the duration scale is 0, an infinite animation snaps to its target and waits; in ComposeTestRule it does not run (chapter C8).')
    a(C + '.goal.g1', 'Đã chạy lượt lặp đầu tiên', 'Ran the first iteration')
    a(C + '.goal.g2', 'Đã chạy một cách lặp tới cuối', 'Ran one repetition to the end')
    a(C + '.sim.animation.repeat', 'Lặp lại và vô hạn', 'Repeating and infinite')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Một hiệu ứng `fadeIn` được lặp bằng `repeatable(10, tween(2000), RepeatMode.Reverse)`. Lượt thứ 10 kết thúc ở alpha nào: 0 hay 1? Và đích của `fadeIn` là gì?', 'A `fadeIn` effect is repeated with `repeatable(10, tween(2000), RepeatMode.Reverse)`. Which alpha does the 10th iteration end at: 0 or 1? And what is `fadeIn`\'s target?')
    B(C, S, 1, 'ans', 'Lượt lẻ đi 0 → 1, lượt chẵn đi 1 → 0, nên lượt 10 kết thúc ở 0, trong khi đích là 1. KDoc của `RepeatableSpec` cảnh báo đúng trường hợp này: với Reverse nên dùng số lượt LẺ, nếu không animation có thể nhảy tới giá trị cuối khi xong. [[src:book-compose-ess]] [[src:an-spec-src]]', 'Odd iterations go 0 → 1, even ones 1 → 0, so iteration 10 ends at 0, while the target is 1. `RepeatableSpec`\'s KDoc warns about exactly this: with Reverse use an ODD count, otherwise the animation may jump to the end value when it finishes. [[src:book-compose-ess]] [[src:an-spec-src]]')

    S = 'repeat'
    a(C + '.sec.%s.title' % S, 'repeatable: lặp một số lần', 'repeatable: repeat a set number of times')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Lặp cũng chỉ là một `AnimationSpec` (chương C2). Hàm `repeatable()` cho một `RepeatableSpec`: ngoài spec được lặp, nó nhận `RepeatMode`, `Restart` (mỗi lượt đi từ đầu tới cuối) hoặc `Reverse` (lượt sau đi ngược từ cuối về đầu). Tài liệu chính thức dùng nó với `animateFloatAsState`; vì là spec, bạn đặt nó vào bất cứ API nào nhận `animationSpec` (animate*AsState, transition, enter/exit). [[src:book-compose-ess]] [[src:an-customize]]', 'Repetition is just another `AnimationSpec` (chapter C2). The `repeatable()` function gives a `RepeatableSpec`: besides the spec to repeat, it takes a `RepeatMode`, `Restart` (each iteration goes from start to end) or `Reverse` (the next iteration goes back from end to start). The official docs use it with `animateFloatAsState`; since it is a spec, you can put it into any API that takes an `animationSpec` (animate*AsState, transitions, enter/exit). [[src:book-compose-ess]] [[src:an-customize]]')
    B(C, S, 2, 'kt', 'val alpha by animateFloatAsState(\n    targetValue = if (blink) 1f else 0f,\n    animationSpec = repeatable(\n        iterations = 3,                              // số LẺ khi dùng Reverse\n        animation = tween(durationMillis = 300),\n        repeatMode = RepeatMode.Reverse,\n        initialStartOffset = StartOffset(100)        // chỉ trễ MỘT lần, không lặp\n    ),\n    label = "blink"\n)', 'val alpha by animateFloatAsState(\n    targetValue = if (blink) 1f else 0f,\n    animationSpec = repeatable(\n        iterations = 3,                              // ODD when using Reverse\n        animation = tween(durationMillis = 300),\n        repeatMode = RepeatMode.Reverse,\n        initialStartOffset = StartOffset(100)        // delays ONCE, not repeated\n    ),\n    label = "blink"\n)')
    B(C, S, 3, 'p', 'Ba chi tiết từ mã ở commit ghim: (1) `repeatable` nhận `DurationBasedAnimationSpec` (tween, keyframes, snap), không nhận spring; mã còn ghi TODO cân nhắc hỗ trợ lặp spring. (2) `iterations` phải ít nhất 1; với `Reverse`, KDoc "rất nên" dùng số lẻ. (3) `initialStartOffset` (kiểu `StartOffset`) chỉ áp dụng MỘT lần ở đầu, còn `delay` bên trong spec được lặp mỗi lượt; `StartOffsetType.Delay` (mặc định) làm trễ, `StartOffsetType.FastForward` bắt đầu ngay nhưng từ giữa chừng. [[src:an-spec-src]]', 'Three details from the code at the pinned commit: (1) `repeatable` takes a `DurationBasedAnimationSpec` (tween, keyframes, snap), not spring; the code even has a TODO to consider supporting repeating springs. (2) `iterations` should be at least 1; with `Reverse`, the KDoc "highly recommends" an odd count. (3) `initialStartOffset` (a `StartOffset`) applies only ONCE at the start, while a `delay` inside the spec is repeated every iteration; `StartOffsetType.Delay` (the default) delays, `StartOffsetType.FastForward` starts at once but from part-way through. [[src:an-spec-src]]')

    S = 'infinite'
    a(C + '.sec.%s.title' % S, 'infiniteRepeatable và rememberInfiniteTransition', 'infiniteRepeatable and rememberInfiniteTransition')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Kunneth mở phần này bằng các thanh tiến trình chạy mãi của Material (`CircularProgressIndicator`, `LinearProgressIndicator`): chúng dùng `InfiniteRepeatableSpec`, lặp tới khi bị hủy. Ví dụ `InfiniteRepeatableDemo` của sách xoay một dòng chữ từ 0 tới 359 độ bằng `rememberInfiniteTransition()` + `animateFloat(…, infiniteRepeatable(keyframes { durationMillis = 1500; 0F at 0; 359F at 1500 }))`; đổi sang `RepeatMode.Reverse` và thêm khoảng nghỉ ở hai đầu thì chữ quay đi rồi quay về. [[src:book-kunneth]]', 'Kunneth opens this part with Material\'s never-ending progress indicators (`CircularProgressIndicator`, `LinearProgressIndicator`): they use an `InfiniteRepeatableSpec`, repeating until cancelled. The book\'s `InfiniteRepeatableDemo` rotates a line of text from 0 to 359 degrees with `rememberInfiniteTransition()` + `animateFloat(…, infiniteRepeatable(keyframes { durationMillis = 1500; 0F at 0; 359F at 1500 }))`; switching to `RepeatMode.Reverse` and adding pauses at both ends makes the text turn and come back. [[src:book-kunneth]]')
    B(C, S, 2, 'p', 'Tài liệu chính thức mô tả `InfiniteTransition` giống `Transition` (chương C3): giữ một hay nhiều animation con (`animateColor`, `animateFloat`, `animateValue`), nhưng chúng chạy NGAY khi vào composition và không dừng trừ khi bị gỡ. Bạn phải truyền một `infiniteRepeatable` làm spec. Từ phiên bản có tham số `label`, nên đặt `label` để phân biệt trong công cụ của Android Studio. [[src:an-value]] [[src:an-inftrans-src]]', 'The official docs describe `InfiniteTransition` as like `Transition` (chapter C3): it holds one or more child animations (`animateColor`, `animateFloat`, `animateValue`), but they run AS SOON AS they enter composition and do not stop unless removed. You must pass an `infiniteRepeatable` as the spec. Since the versions that added the `label` parameter, set a `label` to tell animations apart in Android Studio\'s tools. [[src:an-value]] [[src:an-inftrans-src]]')
    B(C, S, 3, 'kt', 'val infinite = rememberInfiniteTransition(label = "spinner")\nval degrees by infinite.animateFloat(\n    initialValue = 0f,\n    targetValue = 360f,\n    animationSpec = infiniteRepeatable(\n        animation = tween(1200, easing = LinearEasing),\n        repeatMode = RepeatMode.Restart\n    ),\n    label = "degrees"\n)\nIcon(\n    Icons.Default.Refresh, null,\n    Modifier.graphicsLayer { rotationZ = degrees }   // đọc ở phase draw (chương C7)\n)', 'val infinite = rememberInfiniteTransition(label = "spinner")\nval degrees by infinite.animateFloat(\n    initialValue = 0f,\n    targetValue = 360f,\n    animationSpec = infiniteRepeatable(\n        animation = tween(1200, easing = LinearEasing),\n        repeatMode = RepeatMode.Restart\n    ),\n    label = "degrees"\n)\nIcon(\n    Icons.Default.Refresh, null,\n    Modifier.graphicsLayer { rotationZ = degrees }   // read in the draw phase (chapter C7)\n)')
    B(C, S, 4, 'note', 'Ví dụ của Kunneth dùng `Modifier.rotate(degrees = degrees)`: `degrees` được đọc trong thân composable nên composable đó recompose mỗi frame suốt đời animation. Với animation chạy mãi, đọc trong `graphicsLayer { }` như ví dụ trên chỉ làm phase draw chạy lại (chương C7, cầu nối X1). [[src:book-kunneth]] [[src:an-quick]]', 'Kunneth\'s example uses `Modifier.rotate(degrees = degrees)`: `degrees` is read in the composable body, so that composable recomposes every frame for the animation\'s whole life. For an animation that runs forever, reading it in `graphicsLayer { }` as in the example above only re-runs the draw phase (chapter C7, bridge X1). [[src:book-kunneth]] [[src:an-quick]]')
    B(C, S, 4, 'kind', 'pitfall')

    S = 'inside'
    a(C + '.sec.%s.title' % S, 'Bên trong InfiniteTransition', 'Inside InfiniteTransition')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'Ở commit ghim, `rememberInfiniteTransition(label)` chỉ là `remember { InfiniteTransition(label) }` rồi gọi `run()`. `run()` là một composable nội bộ chứa `LaunchedEffect(this)` với vòng `while (true)`: mỗi vòng gọi `withInfiniteAnimationFrameNanos { … }` để chờ frame kế, tính thời gian chơi = (thời điểm frame − mốc bắt đầu) / `durationScale`, rồi báo cho từng con. Vậy animation vô hạn là một coroutine thật chạy trong scope của composition (chương EF và B5 của Runtime). [[src:an-inftrans-src]]', 'At the pinned commit, `rememberInfiniteTransition(label)` is just `remember { InfiniteTransition(label) }` followed by a call to `run()`. `run()` is an internal composable holding a `LaunchedEffect(this)` with a `while (true)` loop: each turn calls `withInfiniteAnimationFrameNanos { … }` to wait for the next frame, computes play time = (frame time − start time) / `durationScale`, then pushes it to each child. So an infinite animation is a real coroutine running in the composition\'s scope (Runtime chapters EF and B5). [[src:an-inftrans-src]]')
    B(C, S, 2, 'p', 'Mỗi con (`animateValue`, và `animateFloat` gọi tới nó) là một `TransitionAnimationState` được `remember`, có `value` là `mutableStateOf`. Con tự thêm vào transition bằng `DisposableEffect` và tự gỡ khi bị dispose. Nếu `initialValue` hoặc `targetValue` đổi, một `SideEffect` tạo animation mới và chạy lại từ đầu ở frame kế; KDoc nói rõ: tính liên tục KHÔNG được giữ. Ngoài ra `InfiniteRepeatableSpec` ném `IllegalArgumentException` nếu spec bên trong có thời lượng 0 (vì sẽ thành vòng lặp vô hạn không tốn thời gian). [[src:an-inftrans-src]] [[src:an-spec-src]]', 'Each child (`animateValue`, which `animateFloat` calls) is a `remember`ed `TransitionAnimationState` whose `value` is a `mutableStateOf`. The child adds itself to the transition with a `DisposableEffect` and removes itself when disposed. If `initialValue` or `targetValue` changes, a `SideEffect` creates a new animation that restarts from the beginning on the next frame; the KDoc says plainly that continuity is NOT preserved. Also, `InfiniteRepeatableSpec` throws an `IllegalArgumentException` if the inner spec has zero duration (it would become an infinite loop that takes no time). [[src:an-inftrans-src]] [[src:an-spec-src]]')
    B(C, S, 3, 'p', 'Tỉ lệ thời lượng (`durationScale`, lấy từ `MotionDurationScale` trong coroutine context) được xử lý riêng: nếu nó đổi, mốc bắt đầu đặt lại và các con chạy lại từ đầu; nếu nó bằng 0, mọi con nhảy tới đích (`skipToEnd`) và vòng lặp treo tới khi tỉ lệ khác 0 (`snapshotFlow { … }.first { it > 0f }`). Mô phỏng ngay dưới cho thấy cả hai nhánh này cùng với các cách lặp hữu hạn. [[src:an-inftrans-src]]', 'The duration scale (`durationScale`, taken from the `MotionDurationScale` in the coroutine context) is handled separately: if it changes, the start time is reset and the children start over; if it is 0, every child snaps to its target (`skipToEnd`) and the loop suspends until the scale is non-zero (`snapshotFlow { … }.first { it > 0f }`). The simulation just below shows both branches alongside the finite ways of repeating. [[src:an-inftrans-src]]')

    S = 'policy'
    a(C + '.sec.%s.title' % S, 'InfiniteAnimationPolicy và kiểm thử', 'InfiniteAnimationPolicy and testing')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', '`withInfiniteAnimationFrameNanos` khác `withFrameNanos` ở một điểm: nếu coroutine context có một `InfiniteAnimationPolicy`, frame được lấy QUA chính sách đó (`policy.onInfiniteOperation { withFrameNanos(onFrame) }`). KDoc của `InfiniteAnimationPolicy` (gói `androidx.compose.ui.platform`): chính sách cho phép can thiệp để biến animation vô hạn thành hữu hạn, ví dụ hủy coroutine; mặc định KHÔNG có chính sách nào, trừ trong test instrumented dùng `ComposeTestRule`. [[src:ui-infpolicy-src]]', '`withInfiniteAnimationFrameNanos` differs from `withFrameNanos` in one way: if the coroutine context has an `InfiniteAnimationPolicy`, the frame is taken THROUGH that policy (`policy.onInfiniteOperation { withFrameNanos(onFrame) }`). The KDoc of `InfiniteAnimationPolicy` (package `androidx.compose.ui.platform`): a policy lets you intervene to make infinite animations finite, for example by cancelling them; by default NO policy is installed, except in instrumented tests using `ComposeTestRule`. [[src:ui-infpolicy-src]]')
    B(C, S, 2, 'p', 'Hệ quả cho test đã có ở chương C8: trong `ComposeTestRule`, animation dùng `infiniteRepeatable` không chạy, và component được vẽ với giá trị ban đầu của mỗi animated value. Nên đừng viết test chờ một spinner "quay xong"; hãy kiểm tra trạng thái dữ liệu hoặc semantics. [[src:an-customize]]', 'The consequence for tests is already in chapter C8: in `ComposeTestRule`, animations using `infiniteRepeatable` do not run, and the component is rendered with each animated value\'s initial value. So do not write a test that waits for a spinner to "finish turning"; check the data state or semantics instead. [[src:an-customize]]')
    B(C, S, 3, 'note', 'Cái gì là "vô hạn" theo nghĩa của chính sách? Những animation lấy frame qua `withInfiniteAnimationFrameNanos`/`Millis`. Ở commit ghim đó là `InfiniteTransition`, và cả animation có spec vô hạn chạy qua `Animatable`/`animate*AsState`: hàm nội bộ `callWithFrameNanos` chọn biến thể vô hạn khi `Animation.isInfinite`. Còn một vòng `while (true) { animatable.animateTo(…) }` tự viết với spec HỮU HẠN thì mỗi lần gọi đi qua `withFrameNanos` thường, nên chính sách không thấy nó là vô hạn. [[src:ui-infpolicy-src]] [[src:an-suspend-src]]', 'What counts as "infinite" for the policy? Animations that take frames through `withInfiniteAnimationFrameNanos`/`Millis`. At the pinned commit that means `InfiniteTransition`, and also animations with an infinite spec running through `Animatable`/`animate*AsState`: the internal `callWithFrameNanos` picks the infinite variant when `Animation.isInfinite`. A hand-written `while (true) { animatable.animateTo(…) }` loop with a FINITE spec, however, goes through plain `withFrameNanos` on each call, so the policy does not see it as infinite. [[src:ui-infpolicy-src]] [[src:an-suspend-src]]')
    B(C, S, 3, 'kind', 'mechanism')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Hiệu ứng nhấp nháy `repeatable(4, tween(300), RepeatMode.Reverse)` kết thúc bằng một cú "giật" sang trạng thái cuối.', 'A blink effect `repeatable(4, tween(300), RepeatMode.Reverse)` ends with a "jerk" to the final state.')
    B(C, S, 1, 'cause', 'Số lượt chẵn với Reverse kết thúc ở giá trị đầu; KDoc cảnh báo animation có thể nhảy tới giá trị cuối khi xong lượt cuối.', 'An even count with Reverse ends at the initial value; the KDoc warns the animation may jump to the end value after the last iteration.')
    B(C, S, 1, 'fix', 'Dùng số lượt lẻ (3 hoặc 5). [[src:an-spec-src]]', 'Use an odd count (3 or 5). [[src:an-spec-src]]')
    B(C, S, 2, 'bug', '`infiniteRepeatable(spring())` không biên dịch.', '`infiniteRepeatable(spring())` does not compile.')
    B(C, S, 2, 'cause', '`infiniteRepeatable` và `repeatable` chỉ nhận `DurationBasedAnimationSpec`; `SpringSpec` không phải loại đó.', '`infiniteRepeatable` and `repeatable` only accept a `DurationBasedAnimationSpec`; `SpringSpec` is not one.')
    B(C, S, 2, 'fix', 'Dùng `tween` hoặc `keyframes` để mô tả một lượt. [[src:an-spec-src]]', 'Use `tween` or `keyframes` to describe one iteration. [[src:an-spec-src]]')
    B(C, S, 3, 'bug', 'Đổi `targetValue` của `animateFloat` trong InfiniteTransition (ví dụ theo chế độ sáng/tối) làm animation giật về đầu.', 'Changing an InfiniteTransition `animateFloat`\'s `targetValue` (say, by light/dark mode) makes the animation snap back to the start.')
    B(C, S, 3, 'cause', 'Theo KDoc và mã: đổi initial/target thì tạo animation mới, chạy lại từ thời gian 0; tính liên tục không được giữ.', 'Per the KDoc and code: changing initial/target creates a new animation restarting at play time 0; continuity is not preserved.')
    B(C, S, 3, 'fix', 'Giữ initial/target cố định và đổi thứ khác ngoài animation (ví dụ nhân giá trị 0..1 với một màu/khoảng cách tính riêng). [[src:an-inftrans-src]]', 'Keep initial/target fixed and change something outside the animation (for example multiply a 0..1 value by a separately computed colour/distance). [[src:an-inftrans-src]]')
    B(C, S, 3, 'fixkt', 'val t by infinite.animateFloat(0f, 1f, infiniteRepeatable(tween(800), RepeatMode.Reverse), label = "t")\nval color = lerp(base, highlight, t)     // base/highlight đổi theo theme, animation không bị làm lại', 'val t by infinite.animateFloat(0f, 1f, infiniteRepeatable(tween(800), RepeatMode.Reverse), label = "t")\nval color = lerp(base, highlight, t)     // base/highlight follow the theme; the animation is not recreated')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Làm "skeleton loading": ba thanh xám nhấp nháy alpha 0.3 ↔ 1, mỗi thanh lệch nhau 150 ms, chạy mãi tới khi dữ liệu về.', 'Build a "skeleton loading" effect: three grey bars pulsing alpha 0.3 ↔ 1, each offset by 150 ms, running until the data arrives.')
    B(C, S, 1, 'hint', 'Một InfiniteTransition, ba `animateFloat`, `initialStartOffset = StartOffset(150 * i)`; ẩn cả khối khi có dữ liệu để animation rời composition.', 'One InfiniteTransition, three `animateFloat`s, `initialStartOffset = StartOffset(150 * i)`; hide the whole block when data arrives so the animation leaves composition.')
    B(C, S, 1, 'solkt', 'if (loading) {\n    val infinite = rememberInfiniteTransition(label = "skeleton")\n    Column {\n        repeat(3) { i ->\n            val a by infinite.animateFloat(\n                0.3f, 1f,\n                infiniteRepeatable(tween(600), RepeatMode.Reverse, StartOffset(150 * i)),\n                label = "bar$i"\n            )\n            Box(Modifier.fillMaxWidth().height(16.dp).graphicsLayer { alpha = a }.background(Color.LightGray))\n        }\n    }\n}', 'if (loading) {\n    val infinite = rememberInfiniteTransition(label = "skeleton")\n    Column {\n        repeat(3) { i ->\n            val a by infinite.animateFloat(\n                0.3f, 1f,\n                infiniteRepeatable(tween(600), RepeatMode.Reverse, StartOffset(150 * i)),\n                label = "bar$i"\n            )\n            Box(Modifier.fillMaxWidth().height(16.dp).graphicsLayer { alpha = a }.background(Color.LightGray))\n        }\n    }\n}')
    B(C, S, 1, 'sol', 'StartOffset chỉ trễ một lần ở đầu nên ba thanh giữ độ lệch pha suốt quá trình; khi `loading = false`, khối rời composition và LaunchedEffect bên trong bị hủy.', 'StartOffset delays only once at the start, so the three bars keep their phase offset throughout; when `loading = false`, the block leaves composition and the LaunchedEffect inside is cancelled.')
    B(C, S, 2, 'ex', 'Cho một nút "Đã lưu" nhấp nháy đúng ba lần rồi đứng yên ở trạng thái hiện.', 'Make a "Saved" button blink exactly three times, then stay visible.')
    B(C, S, 2, 'hint', 'Không cần InfiniteTransition. Một `animateFloatAsState` với `repeatable` số lẻ, mode Reverse.', 'No InfiniteTransition needed. One `animateFloatAsState` with an odd `repeatable`, Reverse mode.')
    B(C, S, 2, 'sol', '`animateFloatAsState(if (saved) 1f else 0f, repeatable(5, tween(200), RepeatMode.Reverse))`: 5 lượt là 0→1→0→1→0→1, tức ba lần hiện và kết thúc ở 1 = đích, không có cú nhảy.', '`animateFloatAsState(if (saved) 1f else 0f, repeatable(5, tween(200), RepeatMode.Reverse))`: 5 iterations go 0→1→0→1→0→1, three appearances ending at 1 = the target, with no jump.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Restart và Reverse khác nhau ở đâu giữa hai lượt?', 'How do Restart and Reverse differ between two iterations?')
    B(C, S, 1, 'ans', 'Restart nhảy về giá trị đầu rồi đi lại; Reverse chơi ngược lượt trước nên liền mạch.', 'Restart jumps back to the initial value and goes again; Reverse plays the previous iteration backwards, so it is continuous.')
    B(C, S, 2, 'ask', 'Một animation trong rememberInfiniteTransition dừng khi nào?', 'When does an animation in rememberInfiniteTransition stop?')
    B(C, S, 2, 'ans', 'Khi rời composition (LaunchedEffect bị hủy, DisposableEffect gỡ con) hoặc bị hủy thủ công; nó không bao giờ tự xong.', 'When it leaves composition (the LaunchedEffect is cancelled, the DisposableEffect removes the child) or is cancelled manually; it never finishes on its own.')
    B(C, S, 3, 'ask', 'Khi durationScale bằng 0 thì InfiniteTransition làm gì?', 'What does InfiniteTransition do when durationScale is 0?')
    B(C, S, 3, 'ans', 'Cho mọi con nhảy tới đích và treo vòng lặp tới khi tỉ lệ khác 0, rồi chạy lại từ đầu.', 'Snaps every child to its target and suspends the loop until the scale is non-zero, then starts over.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'repeatable có nhận spring() không?', 'Does repeatable accept spring()?', 'Không.', 'No.', 'Chỉ nhận DurationBasedAnimationSpec (tween, keyframes, snap).', 'It only accepts a DurationBasedAnimationSpec (tween, keyframes, snap).'),
        ('q2', 'initialStartOffset có lặp lại mỗi lượt không?', 'Is initialStartOffset repeated every iteration?', 'Không.', 'No.', 'Nó chỉ áp dụng một lần; delay bên trong spec mới được lặp.', 'It applies only once; a delay inside the spec is what repeats.'),
        ('q3', 'Đổi targetValue của animateFloat trong InfiniteTransition có giữ tính liên tục?', 'Does changing an InfiniteTransition animateFloat\'s targetValue keep continuity?', 'Không.', 'No.', 'Animation mới được tạo và chạy lại từ đầu.', 'A new animation is created and restarts from the beginning.'),
        ('q4', 'Mặc định có InfiniteAnimationPolicy nào được cài trong app không?', 'Is any InfiniteAnimationPolicy installed in an app by default?', 'Không.', 'No.', 'KDoc: mặc định không có, trừ test instrumented dùng ComposeTestRule.', 'The KDoc: none by default, except in instrumented tests using ComposeTestRule.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
